import React, { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { fetchSchoolAlerts, SchoolAlertItem } from '../api';

const levelOptions = [
  { value: '', label: '全部等级' },
  { value: 'critical', label: '危急' },
  { value: 'high', label: '高危' },
  { value: 'medium', label: '关注' }
];

const statusLabel: Record<string, string> = {
  pending: '待处理',
  contacted: '已联系',
  referred: '已转介',
  closed: '已关闭',
  false_positive: '误报'
};

const SchoolAlerts: React.FC = () => {
  const [alerts, setAlerts] = useState<SchoolAlertItem[]>([]);
  const [level, setLevel] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchSchoolAlerts({
        level: level || undefined,
        from: fromDate ? `${fromDate}T00:00:00.000Z` : undefined
      });
      setAlerts(data.alerts);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, [level, fromDate]);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <div className="school-alerts">
      <div className="school-toolbar">
        <h2>风险告警工作台</h2>
        <select value={level} onChange={(e) => setLevel(e.target.value)}>
          {levelOptions.map((o) => (
            <option key={o.value || 'all'} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
        <label className="school-date-filter">
          起始日期
          <input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} />
        </label>
        <button type="button" className="save-care-btn" onClick={load}>
          刷新
        </button>
      </div>
      <p className="muted school-readonly-hint">可查看学生姓名、学号并跳转至档案查看完整对话。</p>

      {loading && <p className="muted">加载中…</p>}
      {!loading && alerts.length === 0 && <p className="muted">暂无告警记录</p>}

      <div className="school-alert-list">
        {alerts.map((a) => (
          <article key={a.id} className={`school-alert-card level-${a.level}`}>
            <div className="school-alert-head">
              <strong>{a.studentMask}</strong>
              <span className={`badge ${a.level}`}>
                {a.level === 'critical' ? '危急' : a.level === 'high' ? '高危' : '关注'}
              </span>
              <span className="badge status">{statusLabel[a.status] || a.status}</span>
            </div>
            <p>{a.summary}</p>
            {a.riskKeywords.length > 0 && (
              <div className="school-tags">
                {a.riskKeywords.map((k) => (
                  <span key={k} className="group-tag">
                    {k}
                  </span>
                ))}
              </div>
            )}
            <small className="muted">
              {new Date(a.dialogTime).toLocaleString('zh-CN')} · 院系 {a.orgId}
              {a.dialogId ? ` · 会话 ${a.dialogId.slice(0, 16)}` : ''}
            </small>
          </article>
        ))}
      </div>
    </div>
  );
};

export default SchoolAlerts;
